from gurobipy import GRB

model = gp.Model(env=env)

months = [7, 8, 9, 10, 11, 12]

demand_I = {7: 30000, 8: 30000, 9: 30000, 10: 100000, 11: 100000, 12: 100000}
demand_II = {7: 15000, 8: 15000, 9: 15000, 10: 50000, 11: 50000, 12: 50000}

P_I = {}
P_II = {}
I_I = {}
I_II = {}
z = {}
S = {}

