    P_I[m] = model.addVar(lb=0, name=f"P_I_{m}")
    P_II[m] = model.addVar(lb=0, name=f"P_II_{m}")
    I_I[m] = model.addVar(lb=0, name=f"I_I_{m}")
    I_II[m] = model.addVar(lb=0, name=f"I_II_{m}")
    z[m] = model.addVar(name=f"z_{m}")
    S[m] = model.addVar(name=f"S_{m}")

for m in months:
    if m == 7:
        prev_inventory_I = 0
        prev_inventory_II = 0
    else:
        prev_inventory_I = I_I[m - 1]
        prev_inventory_II = I_II[m - 1]
    model.addConstr(prev_inventory_I + P_I[m] - I_I[m] == demand_I[m], name=f"inv_balance_I_{m}")
    model.addConstr(prev_inventory_II + P_II[m] - I_II[m] == demand_II[m], name=f"inv_balance_II_{m}")

for m in months:
    model.addConstr(P_I[m] + P_II[m] <= 120000, name=f"capacity_{m}")

for m in months:
    total_volume = 0.2 * I_I[m] + 0.4 * I_II[m]
    model.addConstr(z[m] >= total_volume - 15000, name=f"z_ge_{m}")
    model.addConstr(z[m] >= 0, name=f"z_ge0_{m}")
    model.addConstr(S[m] == total_volume + 0.5 * z[m], name=f"S_def_{m}")

model.setObjective(gp.quicksum(4.5 * P_I[m] + 7 * P_II[m] + S[m] for m in months), GRB.MINIMIZE)
model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
